// snake_gen: emits programs/snake2/snake.cfg via genlib.
// Direction-symmetric snake rule library. The four cardinal directions share
// one set of patterns parameterised by a Direction struct; per-direction
// rules are generated by iteration. Index.cfg supplies the level seed (random
// walls, food, centred Q) and binds `x` to clear.
//
// State model:
//   Q          — initial spawn marker (placed by index.cfg's ^QCC).
//   g          — ready-to-spawn state (Q → g on first T tick).
//   J,K,U,H    — head per direction (down, right, up, left).
//   s,d,w,a    — just-moved-tail seed (lowercase, written by move rule).
//   S,D,W,A    — settled tail (uppercase, after first T conversion).
//   v,>,^,<    — terminal tail segment (after second T conversion). Stays
//                until the shrink chain erases it.
//   j,k,u,h    — oldest-tail "spawn segment" placed at spawn time.
//                Acts as the chain terminator: when the seed-shift chain
//                reaches it, the cell erases (tail shortens by one).
//
// Tail-follow chain (per move, no food):
//   1. B-tick — head moves forward, leaves seed (s/d/w/a) at old position.
//   2. T-tick — seed + terminal-back → settled, terminal-back → seed (chain
//               propagates one step backward).
//   3. T-tick — settled + spawn_seg-back → terminal segment (chain stable).
//   4. T-tick — when seed reaches the spawn_seg pair, seed → spawn_seg AND
//               spawn_seg-pair erased (shrinks tail by 2 cells).
// With food (move-into-food), step 1 writes terminal segment directly — no
// shrink chain triggered, snake grows.
//
// Game-over (head meets obstacle ahead):
//   Single rule per head + ctx_or_rep over wall # / own-segment chars.
//   5 ctx pairs cover {#, v, ^, <, >} obstacles per direction.
//
// Direction change: head + perpendicular-key → new head glyph (8 rules,
// one per legal turn — 90° only, no 180° reversal).

#include "genlib.h"

#include <iostream>
#include <sstream>
#include <vector>

namespace g = genlib;

struct Direction {
    const char* name;
    wchar_t key;        // player key: a/s/d/w
    wchar_t head;       // J/K/U/H
    wchar_t seed;       // s/d/w/a (lowercase)
    wchar_t settled;    // S/D/W/A (uppercase, post-T1)
    wchar_t terminal;   // v/>/^/< (post-T2, terminal segment)
    wchar_t spawn_seg;  // j/k/u/h (oldest-tail marker, chain terminator)
    int dr, dc;         // movement vector (head moves 1 grid step per B-tick)
};

static const std::vector<Direction> DIRS = {
    //  name      key  head seed  settled term  spawn  dr  dc
    {"down",     L's', L'J', L's', L'S', L'v', L'j',  1,  0},
    {"up",       L'w', L'U', L'w', L'W', L'^', L'u', -1,  0},
    {"right",    L'd', L'K', L'd', L'D', L'>', L'k',  0,  2},
    {"left",     L'a', L'H', L'a', L'A', L'<', L'h',  0, -2},
};

// Pair of cells `k` grid-steps back from anchor along d's direction.
// Snake glyphs are 2-cells-wide pairs; k=1 = previous segment, k=2 = the one
// behind that, etc. For dr=1,dc=0 (down): step-back-1 = (-1, 0..1).
static std::vector<g::Cell> back_pair(const Direction& d, int k) {
    int r = -k * d.dr;
    int c = -k * d.dc;
    return {{r, c}, {r, c + 1}};
}

// Pair of cells one grid-step ahead of anchor.
static std::vector<g::Cell> fwd_pair(const Direction& d) {
    return {{d.dr, d.dc}, {d.dr, d.dc + 1}};
}

// Anchor's pair (head cells (0, 0) and (0, 1)).
static std::vector<g::Cell> head_pair() { return {{0, 1}}; }   // (0, 0) is anchor implicit

static bool perpendicular(const Direction& a, const Direction& b) {
    return (a.dr == 0) != (b.dr == 0);
}

// ---- Rule emitters ----

// Spawn: g + <key> → head, with terminal pair one step back, spawn_seg
// pair two steps back. The two-segment trail at spawn lets the move rule
// (which requires terminal back) fire immediately on first move.
static std::string emit_spawn(const Direction& d) {
    g::LhsPattern lhs;  // anchor only (g)
    g::RhsPattern rhs;
    rhs[{0, 1}] = g::put(d.head);
    auto p1 = back_pair(d, 1);
    auto p2 = back_pair(d, 2);
    for (auto& c : p1) rhs[c] = g::put(d.terminal);
    for (auto& c : p2) rhs[c] = g::put(d.spawn_seg);
    auto h = g::header(L'g', d.key, g::put(d.head));
    return g::emit_rule(h, g::emit_body_horizontal(lhs, rhs));
}

// Move (no food). Three variants per direction handle the three legal
// "what's behind the head" states:
//   v1 (straight)   — d.terminal pair at d's back. Snake just moved in d
//                     before this tick (steady state).
//   v2 (just-turned-from-perp1)  — perp1.terminal pair at perp1's back
//                     (at d's back-left). Snake turned to d on previous
//                     tick; back-segment is still in the old direction.
//   v3 (just-turned-from-perp2)  — perp2.terminal pair at perp2's back.
//
// All three variants share the same RHS (head shifts forward, leaves seed).
// The behind-cell stays in the LHS only; it's not rewritten — the chain of
// settle/shrink rules handles those segments on the T-tick that follows.
static std::string emit_move_variant(const Direction& d, const Direction* back) {
    g::LhsPattern lhs;
    lhs[{0, 1}] = g::lit(d.head);
    for (auto& c : back_pair(*back, 1)) lhs[c] = g::lit(back->terminal);
    for (auto& c : fwd_pair(d))         lhs[c] = g::empty();

    g::RhsPattern rhs;
    rhs[{0, 1}] = g::put(d.seed);
    for (auto& c : fwd_pair(d)) rhs[c] = g::put(d.head);

    auto h = g::header(d.head, L'B', g::put(d.seed));
    h.sound = L'S';
    return g::emit_rule(h, g::emit_body_horizontal(lhs, rhs));
}

static std::string emit_move(const Direction& d, const std::vector<Direction>& all) {
    std::ostringstream out;
    out << emit_move_variant(d, &d) << "\n";   // v1: straight
    for (const auto& p : all) {                // v2, v3: just-turned-from-perp
        if (perpendicular(d, p))
            out << emit_move_variant(d, &p) << "\n";
    }
    return out.str();
}

// Move into food. Three variants mirroring emit_move, but ahead pair = food
// (XX) instead of empty, and the head's old-row becomes terminal segment
// (snake grows, no shrink chain).
static std::string emit_move_food_variant(const Direction& d, const Direction* back) {
    g::LhsPattern lhs;
    lhs[{0, 1}] = g::lit(d.head);
    for (auto& c : back_pair(*back, 1)) lhs[c] = g::lit(back->terminal);
    for (auto& c : fwd_pair(d))         lhs[c] = g::lit(L'X');

    g::RhsPattern rhs;
    rhs[{0, 1}] = g::put(d.terminal);
    for (auto& c : fwd_pair(d)) rhs[c] = g::put(d.head);

    auto h = g::header(d.head, L'B', g::put(d.terminal));
    h.sound = L'B';
    h.score = 1;
    return g::emit_rule(h, g::emit_body_horizontal(lhs, rhs));
}

static std::string emit_move_food(const Direction& d, const std::vector<Direction>& all) {
    std::ostringstream out;
    out << emit_move_food_variant(d, &d) << "\n";
    for (const auto& p : all) {
        if (perpendicular(d, p))
            out << emit_move_food_variant(d, &p) << "\n";
    }
    return out.str();
}

// Tail-follow chain step 1. Three variants per direction d, parameterised by
// `back` — the direction whose terminal sits behind the seed pair:
//   back=d   straight chain (own terminal vv-back).
//   back=p1  just-turned, p1's terminal still in place behind (U-turn).
//   back=p2  just-turned from the other perpendicular.
// All variants: seed → settled at fire-pos; back's terminal → back's seed
// (chain hand-off — when back is a perpendicular, the back-direction's own
// chain takes over).
static std::string emit_tail_step1_variant(const Direction& d, const Direction* back) {
    g::LhsPattern lhs;
    lhs[{0, 1}] = g::lit(d.seed);
    for (auto& c : back_pair(*back, 1)) lhs[c] = g::lit(back->terminal);

    g::RhsPattern rhs;
    rhs[{0, 1}] = g::put(d.settled);
    for (auto& c : back_pair(*back, 1)) rhs[c] = g::put(back->seed);

    auto h = g::header(d.seed, L'T', g::put(d.settled));
    return g::emit_rule(h, g::emit_body_horizontal(lhs, rhs));
}

static std::string emit_tail_step1(const Direction& d, const std::vector<Direction>& all) {
    std::ostringstream out;
    out << emit_tail_step1_variant(d, &d) << "\n";
    for (const auto& p : all) {
        if (perpendicular(d, p))
            out << emit_tail_step1_variant(d, &p) << "\n";
    }
    return out.str();
}

// Tail-follow chain step 2. Three variants per d, parameterised by `back`
// (own or perp): settled → terminal at fire-pos when back's spawn_seg sits
// at back's-back (the chain has reached the snake's tail end in that
// direction).
static std::string emit_tail_step2_variant(const Direction& d, const Direction* back) {
    g::LhsPattern lhs;
    lhs[{0, 1}] = g::lit(d.settled);
    for (auto& c : back_pair(*back, 1)) lhs[c] = g::lit(back->spawn_seg);

    g::RhsPattern rhs;
    rhs[{0, 1}] = g::put(d.terminal);

    auto h = g::header(d.settled, L'T', g::put(d.terminal));
    return g::emit_rule(h, g::emit_body_horizontal(lhs, rhs));
}

static std::string emit_tail_step2(const Direction& d, const std::vector<Direction>& all) {
    std::ostringstream out;
    out << emit_tail_step2_variant(d, &d) << "\n";
    for (const auto& p : all) {
        if (perpendicular(d, p))
            out << emit_tail_step2_variant(d, &p) << "\n";
    }
    return out.str();
}

// Tail-shrink: 3 variants per d. seed pair + back's spawn_seg at back's-back
// → back's spawn_seg shifts forward, original pair erased.
static std::string emit_tail_shrink_variant(const Direction& d, const Direction* back) {
    g::LhsPattern lhs;
    lhs[{0, 1}] = g::lit(d.seed);
    for (auto& c : back_pair(*back, 1)) lhs[c] = g::lit(back->spawn_seg);

    g::RhsPattern rhs;
    rhs[{0, 1}] = g::put(back->spawn_seg);
    for (auto& c : back_pair(*back, 1)) rhs[c] = g::erase();

    auto h = g::header(d.seed, L'T', g::put(back->spawn_seg));
    return g::emit_rule(h, g::emit_body_horizontal(lhs, rhs));
}

static std::string emit_tail_shrink(const Direction& d, const std::vector<Direction>& all) {
    std::ostringstream out;
    out << emit_tail_shrink_variant(d, &d) << "\n";
    for (const auto& p : all) {
        if (perpendicular(d, p))
            out << emit_tail_shrink_variant(d, &p) << "\n";
    }
    return out.str();
}

// Game-over: head + head-right + obstacle-pair-ahead → erase (head removed,
// game over text + sound). One rule per obstacle glyph (#, v, ^, <, >).
// `#` covers walls; the four arrow glyphs cover own-body self-collision.
static std::string emit_game_over(const Direction& d) {
    std::ostringstream out;
    const wchar_t obstacles[] = { L'#', L'v', L'^', L'<', L'>' };
    for (wchar_t obs : obstacles) {
        g::LhsPattern lhs;
        lhs[{0, 1}] = g::lit(d.head);
        for (auto& c : fwd_pair(d)) lhs[c] = g::lit(obs);

        g::RhsPattern rhs;
        // Erase head pair, write "Game Over" text. Place text at offsets
        // (0, 2..10) of the head — i.e. just to the right of the head pair.
        rhs[{0, 0}] = g::erase();
        rhs[{0, 1}] = g::erase();
        const char* text = "Game Over";
        for (int i = 0; text[i]; ++i)
            rhs[{0, 2 + i}] = (text[i] == ' ') ? g::erase()
                                               : g::put(static_cast<wchar_t>(text[i]));

        auto h = g::header(d.head, L'B', g::erase());
        h.sound = L'L';     // shot sound
        h.score = -10;
        out << g::emit_rule(h, g::emit_body_horizontal(lhs, rhs)) << "\n";
    }
    return out.str();
}

// Direction change: from_head pair + to.key → to_head pair. 90° only.
// Both head cells (anchor and (0, 1)) must be matched and rewritten —
// otherwise the head ends up half-in-old / half-in-new state and no move
// rule's LHS can match (since each move expects head + (0, 1) = same head).
static std::string emit_turn(const Direction& from, const Direction& to) {
    g::LhsPattern lhs;
    lhs[{0, 1}] = g::lit(from.head);
    g::RhsPattern rhs;
    rhs[{0, 1}] = g::put(to.head);
    auto h = g::header(from.head, to.key, g::put(to.head));
    return g::emit_rule(h, g::emit_body_horizontal(lhs, rhs));
}

// ---- Framework (header keywords + spawn machinery shared across directions) ----

static const char* FRAMEWORK = R"(#help Snake | a/s/d/w move | x restart
#timing T 0
#grid 2 1
#sound S sounds/click.wav
#sound B sounds/beep.wav
#sound L sounds/shot.wav
#control R return

# Q (placed by level cfg's ^QCC) → g on T tick. g is the "ready to spawn"
# state; pressing any of a/s/d/w fires the corresponding spawn rule below.
==QTg77
@@@~

)";

int main() {
    std::cout << FRAMEWORK;

    std::cout << "# === Spawn rules: g + key → head + initial 2-segment trail ===\n";
    for (const auto& d : DIRS) {
        std::cout << "# spawn " << d.name << "\n";
        std::cout << emit_spawn(d) << "\n";
    }

    std::cout << "# === Move (no food): 3 variants/dir for straight + 2 turn-states ===\n";
    for (const auto& d : DIRS) {
        std::cout << "# move " << d.name << "\n";
        std::cout << emit_move(d, DIRS);
    }

    std::cout << "# === Move into food: 3 variants/dir, snake grows ===\n";
    for (const auto& d : DIRS) {
        std::cout << "# food " << d.name << "\n";
        std::cout << emit_move_food(d, DIRS);
    }

    std::cout << "# === Tail-follow chain step 1: 3 variants/dir (own + 2 perps) ===\n";
    for (const auto& d : DIRS) {
        std::cout << "# step1 " << d.name << "\n";
        std::cout << emit_tail_step1(d, DIRS);
    }

    std::cout << "# === Tail-follow chain step 2: 3 variants/dir (settled → terminal) ===\n";
    for (const auto& d : DIRS) {
        std::cout << "# step2 " << d.name << "\n";
        std::cout << emit_tail_step2(d, DIRS);
    }

    std::cout << "# === Tail shrink: 3 variants/dir (seed reaches spawn_seg) ===\n";
    for (const auto& d : DIRS) {
        std::cout << "# shrink " << d.name << "\n";
        std::cout << emit_tail_shrink(d, DIRS);
    }

    std::cout << "# === Game over: head into wall # or own-body arrow ===\n";
    for (const auto& d : DIRS) {
        std::cout << "# game-over " << d.name << "\n";
        std::cout << emit_game_over(d);
    }
    std::cout << "\n";

    std::cout << "# === Direction change: 90° turns only (no 180° reversal) ===\n";
    for (const auto& from : DIRS) {
        for (const auto& to : DIRS) {
            if (perpendicular(from, to)) {
                std::cout << "# " << from.name << " → " << to.name << "\n";
                std::cout << emit_turn(from, to) << "\n";
            }
        }
    }

    std::cout << "# === Wall + food converters (mirror of legacy snake.cfg) ===\n";
    // z (random wall seed from index.cfg's ^zxX) → ## pair, one-shot.
    // Lowercase z matches the seed; the (0, 1) ~-empty LHS check fires
    // exactly once per z because after firing the cell is # not z.
    std::cout << "==zT#11\n@~@@#\n";
    // x (random food seed from index.cfg's ^xxX) → XX pair, one-shot.
    std::cout << "==xTX22\n@@@X\n";

    return 0;
}
